class Solution {
    public int findMin(int[] nums) {
        int n = nums.length;
        if (nums == null || n == 0) {
            return 0;
        }
        if (n == 1) {
            return nums[0];
        }
        int start = 0;
        int end = n - 1;
        while (start < end) {
            // when there's no rotation, such as [1, 3, 5].
            if (nums[start] < nums[end]) {
                return nums[start];
            }
            int mid = start + (end - start) / 2;
            if (nums[mid] > nums[end]) {
                start = mid + 1;
            } else {
                end = mid;
            } 
        }
        return nums[start];
    }
}
// Time Complexity: O(log(n))
// Space Complexity: O(1)

