// Method 1: use upper bound as the referrence.
class Solution {
    public int findMin(int[] nums) {
        int n = nums.length;
        if (nums == null || n == 0) {
            return 0;
        }
        int start = 0;
        int end = n - 1;
        while (start < end) {
            int mid = start + (end - start) / 2;
            if (nums[mid] > nums[end]) {
                start = mid + 1;
            } else if (nums[mid] < nums[end]) {
                end = mid;
            } else {
                end--;
            }
        }
        return nums[start];
    }
}
// Time Complexity: O(log(n)), the worst case is O(n).
// Space Complexity: O(1)

// Method 2: use lower bound as the referrence.
class Solution {
    public int findMin(int[] nums) {
        int n = nums.length;
        if (nums == null || n == 0) {
            return 0;
        }
        int start = 0;
        int end = n - 1;
        while (start < end) {
            // when there's no rotation, such as [1, 3, 5].
            // Worst case in Method 1 becomes the Best case here!
            if (nums[start] < nums[end]) {
                return nums[start];
            }
            int mid = start + (end - start) / 2;
            if (nums[mid] > nums[start]) {
                start = mid + 1;
            } else if (nums[mid] < nums[start]) {
                end = mid;
            } else {
                start++;
            }
        }
        return nums[start];
    }
}
// Time Complexity: O(log(n))
// Space Complexity: O(1)

