        i, j = 0, len(nums)-1
        while True:
            if i>=j:
                break
            idx = (i+j)/2
            if nums[idx]>nums[0]:
                i = idx+1
            elif nums[idx]<nums[0]:
                j = idx
            elif nums[idx]>nums[-1]:
